/* 2) every card turns over onto its face */
async function rvFlip(tok) {
  rvPhase = 'flip'; await rvSleep(280); if (tok !== rvTok) return; const jobs = [];
  dk.cards.slice().sort((a, b) => b.k - a.k).forEach((c, j) => {
    const dl = j * 85;
    jobs.push(rvGo(c.f, [{ transform: 'rotateY(0deg)' }, { transform: 'rotateY(180deg)' }], 700, 'cubic-bezier(.45,.05,.25,1)', dl));
    c.c.animate([{ transform: c.sc }, { transform: c.sc + ' scale(1.1)', offset: .5 }, { transform: c.sc }], { duration: rvMs(700), delay: rvMs(dl), easing: 'ease-in-out' });
  });
  await Promise.all(jobs);
}
/* 3) they spread out in a fan / circle */
async function rvFan(tok) {
  rvPhase = 'fan'; await rvSleep(300); if (tok !== rvTok) return; const jobs = [], e = 'cubic-bezier(.5,0,.2,1)';
  dk.cards.slice().sort((a, b) => a.k - b.k).forEach((c, j) => {
    jobs.push(rvMv(c, tFan(c), 1000, e, j * 50));
    jobs.push(rvGo(c.c, [{ transform: c.sc }, { transform: RV_ID }], 1000, e, j * 50)); c.sc = RV_ID;
  });
  await Promise.all(jobs);
}

/* a shown card stays 10 s after the last touch, then it leaves, from where it is, to the side it is closest to */
function rvArm(c) { clearTimeout(c.tmr); c.tmr = setTimeout(() => rvExit(c), RV_SHOW); }
function rvSettle(c, cx, cy, rot, s) { c.cx = cx; c.cy = cy; c.rot = rot; c.s = s; c.p = rvCtr(cx, cy, rot, s); }
