  const left = c.cx < dk.cw / 2, x = left ? -dk.W * c.s * .75 : dk.cw + dk.W * c.s * .75;
  await rvMv(c, rvCtr(x, c.cy, c.rot + (left ? -14 : 14), c.s), 750, 'cubic-bezier(.55,0,.85,.45)');
