  const cx = br.left + br.width / 2 - rr.left, cy = br.top + br.height / 2 - rr.top, rot = Math.atan2(m.b, m.a) * 180 / Math.PI, s = Math.hypot(m.a, m.b), fromDeck = c.st === 'deck';
